function get_filtered_historical_records($monthStart, $monthEnd, $audience = 'ALL', $category = 'ALL') {
    $records = get_historical_dataset_records();
    $filtered = [];
    $maxAllowedDate = date('Y-m-d 23:59:59');

    foreach ($records as $r) {
        $dateStr = $r['date'] ?? '';
        if (!$dateStr || $dateStr > $maxAllowedDate) continue;

        // Date filter
        if ($monthStart !== '1970-01-01 00:00:00') {
            if ($dateStr < $monthStart || $dateStr > $monthEnd) continue;
        }

        // Audience filter
        if ($audience === 'SHS') {
            $isShs = (strpos(strtoupper($r['program']), 'SHS') !== false || strpos(strtoupper($r['program']), 'SENIOR') !== false);
            if (!$isShs) continue;
        } elseif ($audience === 'COLLEGE') {
            $isShs = (strpos(strtoupper($r['program']), 'SHS') !== false || strpos(strtoupper($r['program']), 'SENIOR') !== false);
            if ($isShs) continue;
        }

        // Category filter
        $lvl = strtoupper($r['level'] ?? 'MINOR');
        if ($category === 'MINOR' && $lvl !== 'MINOR') continue;
        if (($category === 'MAJOR_SANCTIONS' || $category === 'MAJOR' || $category === 'SANCTIONS') && $lvl !== 'MAJOR' && empty($r['sanction'])) continue;
        if ($category === 'DISMISSED' && strpos(strtoupper($r['sanction'] ?? ''), 'DISMISS') === false) continue;

        $filtered[] = $r;
    }
    return $filtered;
}
